# Largest Product in a Series
# https://projecteuler.net/problem=8

"""



Find the thirteen adjacent digits in the 1000-digit number that have the greatest product. What is the value of this product?

pointer of the number between 13 digits and skip when the back pointer touches 0?

"""

def largest_product_in_series(series, length):
    digits = [int(d) for d in series]
    n = len(digits)
    if n < length:
        return 0

    max_product = 0
    current_product = 1
    zero_count = 0
    left = 0

    for right in range(n):
        d = digits[right]
        if d == 0:
            zero_count += 1
        else:
            current_product *= d

        if right - left + 1 > length:
            left_d = digits[left]
            if left_d == 0:
                zero_count -= 1
            else:
                current_product //= left_d
            left += 1

        if right - left + 1 == length and zero_count == 0:
            if current_product > max_product:
                max_product = current_product

    return max_product

print(largest_product_in_series(
    "", 13))
